import type { PublicSnapshot } from './types';

const TOLERANCE = 1e-6;

export interface ModelAuditCheck {
  key: 'TARGET_SUM' | 'EQUITY_RECONCILIATION' | 'GROUP_RECONCILIATION' | 'BOUNDS' | 'TIMING' | 'DECISION_INTEGRITY';
  label: string;
  passed: boolean;
  detail: string;
}

export interface ModelAuditResult {
  passed: boolean;
  checks: ModelAuditCheck[];
  issues: string[];
}

function close(left: number, right: number): boolean {
  return Number.isFinite(left) && Number.isFinite(right) && Math.abs(left - right) <= TOLERANCE;
}

export function auditSnapshotModel(snapshot: PublicSnapshot): ModelAuditResult {
  const targets = snapshot.assets.map((asset) => asset.confirmedTarget);
  const targetSum = targets.reduce((sum, value) => sum + value, 0);
  const validTargets = targets.every((value) => Number.isFinite(value) && value >= 0 && value <= 1);
  const equities = snapshot.assets.filter((asset) => asset.assetClass === 'EQUITY');
  const equityTarget = equities.reduce((sum, asset) => sum + asset.confirmedTarget, 0);
  const defenses = snapshot.assets.filter((asset) => asset.assetClass !== 'EQUITY');
  const defenseTarget = defenses.reduce((sum, asset) => sum + asset.confirmedTarget, 0);

  const groupIssues: string[] = [];
  (['CORE', 'SATELLITE'] as const).forEach((group) => {
    const members = snapshot.assets.filter((asset) => asset.targetFormation.allocationGroup === group);
    if (!members.length) return;
    const shareSum = members.reduce((sum, asset) => sum + asset.targetFormation.finalGroupShare, 0);
    const target = members[0]?.targetFormation.groupTarget;
    const targetSumForGroup = members.reduce((sum, asset) => sum + asset.confirmedTarget, 0);
    if (!close(shareSum, 1)) groupIssues.push(`${group}组内比例合计不是100%`);
    if (target == null || !close(targetSumForGroup, target)) groupIssues.push(`${group}组预算与ETF目标不一致`);
  });
  if (!close(defenseTarget, 1 - equityTarget)) groupIssues.push('防御目标未承接全部非权益预算');

  const boundIssues = snapshot.assets.flatMap((asset) => {
    const formation = asset.targetFormation;
    const observed = formation.boundScope === 'PORTFOLIO' ? asset.confirmedTarget : formation.finalGroupShare;
    return observed + TOLERANCE < formation.floor || observed - TOLERANCE > formation.cap
      ? [`${asset.code}超出${formation.boundScope === 'PORTFOLIO' ? '组合' : '组内'}上下限`]
      : [];
  });

  const signalTime = Date.parse(`${snapshot.meta.confirmedSignalDate}T00:00:00Z`);
  const effectiveTime = Date.parse(`${snapshot.meta.confirmedEffectiveDate}T00:00:00Z`);
  const timingPassed = snapshot.timingAudit.status === 'PASS'
    && snapshot.timingAudit.signalAtClose
    && snapshot.timingAudit.positionShiftTradingDays === 1
    && snapshot.timingAudit.monthEndOnly
    && snapshot.timingAudit.adjustedPriceOnly
    && snapshot.timingAudit.valuationPriceSeparated === true
    && snapshot.timingAudit.premiumGateSeparated
    && Number.isFinite(signalTime)
    && Number.isFinite(effectiveTime)
    && effectiveTime > signalTime;
  const decisions = snapshot.decisionLog ?? [];
  const decisionLinksValid = decisions.every((entry, index) => {
    const expectedPrevious = index === 0 ? 'GENESIS' : decisions[index - 1]?.recordHash;
    return entry.previousHash === expectedPrevious && /^[a-f0-9]{64}$/.test(entry.recordHash ?? '');
  });
  const decisionIntegrityPassed = snapshot.decisionIntegrity?.status === 'PASS'
    && snapshot.decisionIntegrity.appendOnly === true
    && snapshot.decisionIntegrity.entries === decisions.length
    && snapshot.decisionIntegrity.latestHash === (decisions.at(-1)?.recordHash ?? 'GENESIS')
    && decisionLinksValid;

  const checks: ModelAuditCheck[] = [
    {
      key: 'TARGET_SUM', label: '组合目标守恒', passed: validTargets && close(targetSum, 1),
      detail: `7只ETF确认目标合计 ${(targetSum * 100).toFixed(4)}%`,
    },
    {
      key: 'EQUITY_RECONCILIATION', label: '权益目标对账', passed: close(equityTarget, snapshot.risk.confirmedEquityTarget),
      detail: `ETF权益合计 ${(equityTarget * 100).toFixed(2)}%，风险引擎目标 ${(snapshot.risk.confirmedEquityTarget * 100).toFixed(2)}%`,
    },
    {
      key: 'GROUP_RECONCILIATION', label: '分组预算守恒', passed: groupIssues.length === 0,
      detail: groupIssues.length ? groupIssues.join('；') : `权益 ${(equityTarget * 100).toFixed(2)}% + 防御 ${(defenseTarget * 100).toFixed(2)}%`,
    },
    {
      key: 'BOUNDS', label: '上下限约束', passed: boundIssues.length === 0,
      detail: boundIssues.length ? boundIssues.join('；') : '所有ETF均满足其组内或组合绝对边界',
    },
    {
      key: 'TIMING', label: '信号时序', passed: timingPassed,
      detail: `${snapshot.meta.confirmedSignalDate}收盘确认，${snapshot.meta.confirmedEffectiveDate}起可用于人工建议`,
    },
    {
      key: 'DECISION_INTEGRITY', label: '决策链完整性', passed: decisionIntegrityPassed,
      detail: decisionIntegrityPassed ? `${decisions.length}条记录追加写入，链首到链尾引用完整` : '决策日志缺少有效的追加写入哈希链',
    },
  ];
  const issues = checks.filter((check) => !check.passed).map((check) => `${check.label}：${check.detail}`);
  return { passed: issues.length === 0, checks, issues };
}
