import type { AdviceRow, AssetCode, LocalAdviceRecord, LocalPortfolio, PublicAsset, PublicSnapshot, QDIIDeferral } from './types';
import { ASSET_CODES } from './types';
import { createEmptyPortfolio, migratePortfolio, validateLocalPortfolio } from './portfolio-ledger';

type ExecutionModel = PublicSnapshot['executionModel'];

export interface AdviceResult {
  available: boolean;
  adviceAllowed: boolean;
  blockedReason: string | null;
  /** 当前已经发生的资产：持仓市值 + 现金，不含计划投入。 */
  recordedValue: number;
  /** 调仓规划口径：只含当前已发生资产；计划投入不进入本期预算。 */
  totalValue: number;
  currentWeights: Record<AssetCode, number>;
  currentEquity: number;
  modelEquityTarget: number;
  executionEquityTarget: number;
  cashWeight: number;
  premiumStatus: string;
  premiumStatuses: Partial<Record<AssetCode, string>>;
  premiumRequired: boolean;
  premiumRequiredByCode: Partial<Record<AssetCode, boolean>>;
  qdiiWithheldAmounts: Partial<Record<AssetCode, number>>;
  holdingsFresh: boolean;
  premiumFresh: boolean;
  premiumFreshByCode: Partial<Record<AssetCode, boolean>>;
  cashAvailable: number;
  estimatedTransactionCost: number;
  cashAfterPlan: number;
  signalConfirmed: boolean;
  signalEffective: boolean;
  localIssues: string[];
  rows: AdviceRow[];
}

export function emptyPortfolio(): LocalPortfolio {
  return createEmptyPortfolio();
}

export function normalizePortfolio(input?: LocalPortfolio | null): LocalPortfolio {
  return migratePortfolio(input);
}

function ageHours(value: string | null | undefined, now: Date): number {
  const parsed = value ? new Date(value).getTime() : Number.NaN;
  return Number.isFinite(parsed) ? Math.max(0, now.getTime() - parsed) / 3_600_000 : Number.POSITIVE_INFINITY;
}

function premiumStatus(premium: number | null, fresh: boolean, model: ExecutionModel): string {
  if (premium == null || !Number.isFinite(premium)) return '需要人工输入';
  if (!fresh) return '溢价已过期 · 禁止新增';
  if (premium >= model.premiumGate.redWarningThreshold) return 'RED WARNING';
  if (premium >= model.premiumGate.blockBuyThreshold) return '禁止新增买入';
  if (premium >= model.premiumGate.halfBuyThreshold) return `仅执行${Math.round(model.premiumGate.halfBuyFactor * 100)}%买入`;
  return '正常';
}

function confirmedTargets(assets: PublicAsset[]): {
  targets: Record<AssetCode, number>;
  modelEquity: number;
} {
  const targets = Object.fromEntries(ASSET_CODES.map((code) => [code, 0])) as Record<AssetCode, number>;
  assets.forEach((asset) => { targets[asset.code] = asset.confirmedTarget; });
  const equities = assets.filter((asset) => asset.assetClass === 'EQUITY').map((asset) => asset.code);
  const modelEquity = equities.reduce((sum, code) => sum + targets[code], 0);
  return { targets, modelEquity };
}

export function calculateAdvice(
  rawPortfolio: LocalPortfolio,
  assets: PublicAsset[],
  model: ExecutionModel,
  health: Pick<PublicSnapshot['health'], 'blocking' | 'summary'> & {
    targetStatus?: string;
    confirmedSignalDate?: string;
    confirmedEffectiveDate?: string;
  } = { blocking: false, summary: '' },
  now = new Date(),
): AdviceResult {
  const portfolio = normalizePortfolio(rawPortfolio);
  const localIssues = validateLocalPortfolio(portfolio, assets);
  const codes = assets.map((asset) => asset.code);
  const equities = assets.filter((asset) => asset.assetClass === 'EQUITY').map((asset) => asset.code);
  const qdiiCodes = (model.qdiiCodes?.filter((code) => codes.includes(code))
    ?? assets.filter((asset) => asset.qdii).map((asset) => asset.code));
  if (!qdiiCodes.length && codes.includes('513100')) qdiiCodes.push('513100');
  const invested = codes.reduce((total, code) => total + Math.max(0, portfolio.values[code] || 0), 0);
  const cash = Math.max(0, portfolio.cash || 0);
  const recordedValue = invested + cash;
  const totalValue = recordedValue;
  const available = recordedValue > 0;
  // The user explicitly defines scope by what is entered into this portfolio.
  // Therefore all portfolio cash is available to the rebalance solver; emergency
  // or near-term spending money must remain outside this ledger.
  const investableCash = cash;
  const signalConfirmed = health.targetStatus == null || health.targetStatus === 'CONFIRMED';
  const effectiveAt = health.confirmedEffectiveDate ? Date.parse(`${health.confirmedEffectiveDate}T00:00:00+08:00`) : Number.NaN;
  const signalEffective = health.confirmedEffectiveDate == null || (Number.isFinite(effectiveAt) && now.getTime() >= effectiveAt);
  const holdingsFresh = ageHours(portfolio.updatedAt, now) <= model.freshness.holdingsMaxAgeDays * 24;
  const premiumFreshByCode: Partial<Record<AssetCode, boolean>> = {};
  const premiumStatuses: Partial<Record<AssetCode, string>> = {};
  qdiiCodes.forEach((code) => {
    const fresh = ageHours(portfolio.qdiiPremiumUpdatedAtByCode?.[code], now) <= model.freshness.premiumMaxAgeHours;
    premiumFreshByCode[code] = fresh;
    premiumStatuses[code] = premiumStatus(portfolio.qdiiPremiums?.[code] ?? null, fresh, model);
  });
  const currentWeights = Object.fromEntries(ASSET_CODES.map((code) => [
    code, recordedValue > 0 ? Math.max(0, portfolio.values[code] || 0) / recordedValue : 0,
  ])) as Record<AssetCode, number>;
  const planningWeights = Object.fromEntries(ASSET_CODES.map((code) => [
    code, totalValue > 0 ? Math.max(0, portfolio.values[code] || 0) / totalValue : 0,
  ])) as Record<AssetCode, number>;
  const { targets: target, modelEquity } = confirmedTargets(assets);
  const blockedReason = health.blocking
    ? `数据闸门已关闭：${health.summary || '数据健康检查未通过'}`
    : localIssues.length
      ? `本机资产记录异常：${localIssues.join('；')}`
    : !available
      ? '尚未录入本机持仓'
      : !holdingsFresh
        ? `持仓已超过 ${model.freshness.holdingsMaxAgeDays} 天未更新`
        : !signalConfirmed
          ? '正式目标尚未完成月末确认，日频与周频状态只用于观察'
          : !signalEffective
            ? `月末确认目标最早于 ${health.confirmedEffectiveDate} 起可用于人工建议`
            : null;
  const adviceAllowed = blockedReason == null;
  const gaps = Object.fromEntries(codes.map((code) => [code, (target[code] ?? 0) - planningWeights[code]])) as Partial<Record<AssetCode, number>>;
  const bands = Object.fromEntries(codes.map((code) => [
    code, Math.max(model.rebalance.absoluteBand, model.rebalance.relativeBand * (target[code] ?? 0)),
  ])) as Partial<Record<AssetCode, number>>;
  const deltas = Object.fromEntries(codes.map((code) => [
    code, adviceAllowed && Math.abs(gaps[code] ?? 0) >= (bands[code] ?? 0) ? model.rebalance.partialFactor * (gaps[code] ?? 0) : 0,
  ])) as Partial<Record<AssetCode, number>>;

  const buys = codes.reduce((sum, code) => sum + Math.max(0, deltas[code] ?? 0), 0);
  const sells = codes.reduce((sum, code) => sum + Math.max(0, -(deltas[code] ?? 0)), 0);
  const buyBudget = sells + (totalValue > 0 ? investableCash / totalValue : 0);
  if (buys > buyBudget && buys > 0) {
    const factor = buyBudget / buys;
    codes.forEach((code) => { if ((deltas[code] ?? 0) > 0) deltas[code] = (deltas[code] ?? 0) * factor; });
  } else if (sells > buys && sells > 0) {
    const factor = buys / sells;
    codes.forEach((code) => { if ((deltas[code] ?? 0) < 0) deltas[code] = (deltas[code] ?? 0) * factor; });
  }

  const premiumRequiredByCode = Object.fromEntries(qdiiCodes.map((code) => [
    code, (deltas[code] ?? 0) > 0,
  ])) as Partial<Record<AssetCode, boolean>>;
  const premiumRequired = qdiiCodes.some((code) => premiumRequiredByCode[code] === true);
  const premiumFresh = qdiiCodes.every((code) => (
    !premiumRequiredByCode[code] || premiumFreshByCode[code] === true
  ));
  const divertedByCode: Partial<Record<AssetCode, number>> = {};
  qdiiCodes.forEach((code) => {
    const original = Math.max(0, deltas[code] ?? 0);
    const premium = portfolio.qdiiPremiums?.[code] ?? null;
    let factor = 1;
    if (premium == null || !premiumFreshByCode[code] || premium >= model.premiumGate.blockBuyThreshold) factor = 0;
    else if (premium >= model.premiumGate.halfBuyThreshold) factor = model.premiumGate.halfBuyFactor;
    deltas[code] = original * factor;
    divertedByCode[code] = original - (deltas[code] ?? 0);
  });
  const totalDiverted = qdiiCodes.reduce((sum, code) => sum + (divertedByCode[code] ?? 0), 0);
  const bondCode = assets.find((asset) => asset.assetClass === 'BOND')?.code;
  if (bondCode) deltas[bondCode] = (deltas[bondCode] ?? 0) + totalDiverted;

  const continuousAmounts = Object.fromEntries(codes.map((code) => [
    code, (deltas[code] ?? 0) * totalValue,
  ])) as Record<AssetCode, number>;
  const executableShares = Object.fromEntries(codes.map((code) => {
    const asset = assets.find((item) => item.code === code);
    const lotSize = asset?.lotSize || model.defaultLotSize;
    const price = asset?.valuationClose || 0;
    const amount = continuousAmounts[code];
    let magnitude = price > 0 ? Math.floor(Math.abs(amount) / price / lotSize) * lotSize : 0;
    if (amount < 0) {
      const position = portfolio.positionsByCode?.[code];
      const maximumShares = position?.inputMode === 'QUANTITY' && position.quantity != null
        ? Math.floor(position.quantity / lotSize) * lotSize
        : price > 0 ? Math.floor(Math.max(0, portfolio.values[code] || 0) / price / lotSize) * lotSize : 0;
      magnitude = Math.min(magnitude, maximumShares);
    }
    return [code, Math.sign(amount) * magnitude];
  })) as Record<AssetCode, number>;
  const costRate = Math.max(0, model.transactionCost ?? .0005);
  const sellProceeds = codes.reduce((sum, code) => {
    const price = assets.find((item) => item.code === code)?.valuationClose ?? 0;
    return sum + Math.max(0, -executableShares[code] * price);
  }, 0);
  const sellCost = sellProceeds * costRate;
  const buyBudgetAmount = investableCash + sellProceeds - sellCost;
  const plannedBuyCost = () => codes.reduce((sum, code) => {
    const price = assets.find((item) => item.code === code)?.valuationClose ?? 0;
    const amount = Math.max(0, executableShares[code] * price);
    return sum + amount * (1 + costRate);
  }, 0);
  let solveGuard = 100_000;
  while (plannedBuyCost() > buyBudgetAmount + 1e-8 && solveGuard > 0) {
    const candidates = codes.filter((code) => executableShares[code] > 0).sort((left, right) => {
      const leftAsset = assets.find((item) => item.code === left);
      const rightAsset = assets.find((item) => item.code === right);
      const leftLotWeight = ((leftAsset?.valuationClose ?? 0) * (leftAsset?.lotSize || model.defaultLotSize)) / Math.max(totalValue, 1);
      const rightLotWeight = ((rightAsset?.valuationClose ?? 0) * (rightAsset?.lotSize || model.defaultLotSize)) / Math.max(totalValue, 1);
      const leftPriority = Math.abs(gaps[left] ?? 0) / Math.max(leftLotWeight, 1e-12);
      const rightPriority = Math.abs(gaps[right] ?? 0) / Math.max(rightLotWeight, 1e-12);
      return leftPriority - rightPriority || left.localeCompare(right);
    });
    const code = candidates[0];
    if (!code) break;
    const lotSize = assets.find((item) => item.code === code)?.lotSize || model.defaultLotSize;
    executableShares[code] = Math.max(0, executableShares[code] - lotSize);
    solveGuard -= 1;
  }
  const executableAmounts = Object.fromEntries(codes.map((code) => {
    const price = assets.find((item) => item.code === code)?.valuationClose ?? 0;
    return [code, executableShares[code] * price];
  })) as Record<AssetCode, number>;
  const estimatedTransactionCost = codes.reduce((sum, code) => sum + Math.abs(executableAmounts[code]) * costRate, 0);
  const cashAfterPlan = cash - codes.reduce((sum, code) => sum + executableAmounts[code], 0) - estimatedTransactionCost;
  const planValue = Math.max(0, totalValue - estimatedTransactionCost);

  const rows = codes.map((code): AdviceRow => {
    const continuousTradeWeight = deltas[code] ?? 0;
    const continuousAmount = continuousAmounts[code];
    const suggestedShares = executableShares[code];
    const roundedAmount = executableAmounts[code];
    const tradeWeight = totalValue > 0 ? roundedAmount / totalValue : 0;
    const plannedWeight = planValue > 0 ? (Math.max(0, portfolio.values[code] || 0) + roundedAmount) / planValue : 0;
    let action: AdviceRow['action'] = 'NO TRADE';
    let reason = !adviceAllowed ? blockedReason ?? '执行输入不可用' : Math.abs(gaps[code] ?? 0) < (bands[code] ?? 0) ? '处于免交易区间内' : '连续计划不足一手，或受现金与整手约束后不产生建议';
    if (suggestedShares > 0) { action = 'BUY'; reason = `按目标缺口的${Math.round(model.rebalance.partialFactor * 100)}%进行部分再平衡，并按整手与现金约束求解`; }
    if (suggestedShares < 0) { action = 'SELL'; reason = `按目标缺口的${Math.round(model.rebalance.partialFactor * 100)}%进行部分再平衡，并按可用份额求解`; }
    if (investableCash > 0 && action === 'BUY') reason += '，使用组合内现金';
    if ((divertedByCode[code] ?? 0) > 0) reason = '该QDII溢价缺失、过期或超限，限制新增买入但不改变模型目标';
    if (code === bondCode && totalDiverted > 0) reason = '暂时承接被QDII溢价门控拦截的计划资金';
    return {
      code, currentWeight: currentWeights[code], targetWeight: target[code] ?? 0,
      gap: gaps[code] ?? 0, remainingGap: (target[code] ?? 0) - plannedWeight,
      band: bands[code] ?? 0, tradeWeight, continuousTradeWeight, continuousAmount,
      suggestedAmount: roundedAmount, suggestedShares, roundedAmount,
      roundingResidual: continuousAmount - roundedAmount,
      estimatedCost: Math.abs(roundedAmount) * costRate, plannedWeight,
      action, reason,
    };
  });
  const firstQdii = qdiiCodes[0];
  return {
    available, adviceAllowed, blockedReason, recordedValue, totalValue, currentWeights,
    currentEquity: equities.reduce((sum, code) => sum + currentWeights[code], 0),
    modelEquityTarget: modelEquity, executionEquityTarget: modelEquity,
    cashWeight: recordedValue > 0 ? cash / recordedValue : 0,
    premiumStatus: firstQdii ? premiumStatuses[firstQdii] ?? '需要人工输入' : '不适用',
    premiumStatuses, premiumRequired, premiumRequiredByCode,
    qdiiWithheldAmounts: Object.fromEntries(qdiiCodes.map((code) => [code, (divertedByCode[code] ?? 0) * totalValue])),
    holdingsFresh, premiumFresh, premiumFreshByCode,
    cashAvailable: investableCash, estimatedTransactionCost, cashAfterPlan,
    signalConfirmed, signalEffective, localIssues, rows,
  };
}

export function buildAdviceAuditRecord(
  portfolio: LocalPortfolio,
  snapshot: PublicSnapshot,
  advice: AdviceResult,
  now = new Date().toISOString(),
): { record: LocalAdviceRecord; deferrals: QDIIDeferral[] } {
  if (!advice.adviceAllowed) throw new Error(advice.blockedReason ?? '当前不能保存建议');
  const latestSnapshot = [...(portfolio.snapshots ?? [])].filter((item) => !item.supersededBy).sort((a, b) => a.createdAt.localeCompare(b.createdAt)).at(-1);
  const adviceId = `ASSET-${snapshot.meta.confirmedSignalDate}-${latestSnapshot?.id ?? 'NO-HOLDINGS'}`;
  const effectiveTime = Date.parse(`${snapshot.meta.confirmedEffectiveDate}T00:00:00+08:00`);
  const expiresAt = Number.isFinite(effectiveTime)
    ? new Date(effectiveTime + 45 * 86_400_000).toISOString().slice(0, 10)
    : snapshot.meta.confirmedEffectiveDate;
  const modelTargets = Object.fromEntries(snapshot.assets.map((asset) => [asset.code, asset.confirmedTarget]));
  const householdTargets = Object.fromEntries(advice.rows.map((row) => [row.code, row.targetWeight]));
  const executableShares = Object.fromEntries(advice.rows.map((row) => [row.code, row.suggestedShares]));
  const plannedAmounts = Object.fromEntries(advice.rows.map((row) => [row.code, row.roundedAmount]));
  const plannedPrices = Object.fromEntries(snapshot.assets.map((asset) => [asset.code, asset.valuationClose ?? 0]));
  const plannedEstimatedCosts = Object.fromEntries(advice.rows.map((row) => [row.code, row.estimatedCost]));
  const reasons = Object.fromEntries(advice.rows.map((row) => [row.code, row.reason]));
  const record: LocalAdviceRecord = {
    adviceId,
    signalDate: snapshot.meta.confirmedSignalDate,
    effectiveDate: snapshot.meta.confirmedEffectiveDate,
    expiresAt,
    createdAt: now,
    holdingsSnapshotId: latestSnapshot?.id ?? null,
    modelTargets,
    householdTargets,
    executableShares,
    plannedAmounts,
    plannedPrices,
    plannedEstimatedCosts,
    reasons,
    status: 'UNEXECUTED',
  };
  const bond = snapshot.assets.find((asset) => asset.assetClass === 'BOND')?.code ?? '511010';
  const deferrals = Object.entries(advice.qdiiWithheldAmounts).flatMap(([rawCode, withheldAmount]) => {
    const code = rawCode as AssetCode;
    if (!withheldAmount || withheldAmount <= 1e-8) return [];
    const premium = portfolio.qdiiPremiums?.[code] ?? null;
    const continuous = advice.rows.find((row) => row.code === code)?.continuousAmount ?? 0;
    const originalAmount = Math.max(0, continuous + withheldAmount);
    return [{
      id: `qdii-${adviceId}-${code}`,
      adviceId,
      code,
      originalAmount,
      allowedFactor: originalAmount > 0 ? Math.max(0, Math.min(1, (originalAmount - withheldAmount) / originalAmount)) : 0,
      withheldAmount,
      parkedIn: bond,
      premium,
      premiumUpdatedAt: portfolio.qdiiPremiumUpdatedAtByCode?.[code] ?? null,
      createdAt: now,
      reviewDate: snapshot.meta.confirmedEffectiveDate,
      status: 'DEFERRED' as const,
    }];
  });
  return { record, deferrals };
}
