import { ASSET_CODES, type AdviceStatusEvent, type AssetCode, type CashFlowEvent, type ExecutionFill, type FundBuckets, type IPSPolicy, type IPSPolicyStatus, type LocalAdviceRecord, type LocalPortfolio, type LocalPosition, type MonthlyReview, type PublicAsset, type QDIIDeferral, type QDIIDeferralEvent } from './types';

export interface PositionInput {
  code: AssetCode;
  inputMode: LocalPosition['inputMode'];
  amount: number;
}

export interface CashFlowInput {
  date: string;
  type: CashFlowEvent['type'];
  amount: number;
  note: string;
}

export interface ExecutionReportInput {
  adviceId: string;
  status: 'PARTIAL' | 'EXECUTED';
  tradeDate: string;
  fills: ExecutionFill[];
  actualCashAfter: number;
  note: string;
}

function recordId(prefix: string, now: string): string {
  const random = globalThis.crypto?.randomUUID?.() ?? Math.random().toString(36).slice(2);
  return `${prefix}-${now.replace(/\D/g, '').slice(0, 14)}-${random}`;
}

function emptyPositions(): Partial<Record<AssetCode, LocalPosition>> {
  return Object.fromEntries(ASSET_CODES.map((code) => [code, {
    code,
    inputMode: 'MARKET_VALUE',
    quantity: null,
    confirmedMarketValue: 0,
    confirmedAt: null,
    estimationStatus: 'UNCONFIRMED',
  }])) as Partial<Record<AssetCode, LocalPosition>>;
}

function emptyIPSPolicy(): IPSPolicy {
  return {
    enabled: false,
    status: 'UNSET',
    managedScope: '七只ETF与组合内现金',
    emergencyFundReady: null,
    householdEquityCap: null,
    liabilityEquityCap: null,
    horizonYears: null,
    maxTolerableDrawdown: null,
    contributionStability: 'UNSET',
    confirmedAt: null,
    reviewDueDate: null,
    expiresAt: null,
    confirmedBy: '',
  };
}

function emptyFundBuckets(): FundBuckets {
  return {
    emergencyReserveExcluded: null,
    nearTermNeeds12Months: null,
    nearTermNeeds13To36Months: null,
    nearTermNeeds37To60Months: null,
    investableCash: 0,
    confirmedAt: null,
  };
}

export function resolveIPSPolicyStatus(policy?: IPSPolicy | null, now = new Date()): IPSPolicyStatus {
  if (!policy?.enabled) return 'UNSET';
  if (!policy.confirmedAt) return 'DRAFT';
  const today = now.toISOString().slice(0, 10);
  if (policy.expiresAt && today > policy.expiresAt) return 'EXPIRED';
  if (policy.reviewDueDate && today >= policy.reviewDueDate) return 'DUE';
  return 'CONFIRMED';
}

export function createEmptyPortfolio(): LocalPortfolio {
  return {
    schemaVersion: 6,
    updatedAt: new Date(0).toISOString(),
    values: Object.fromEntries(ASSET_CODES.map((code) => [code, 0])),
    positionsByCode: emptyPositions(),
    cash: 0,
    qdiiPremiums: { '513500': null, '513100': null },
    qdiiPremiumUpdatedAtByCode: { '513500': null, '513100': null },
    monthlyContribution: 0,
    plannedMonthlyContribution: 0,
    baseline: null,
    snapshots: [],
    cashFlows: [],
    corrections: [],
    adviceRecords: [],
    adviceStatusEvents: [],
    qdiiDeferrals: [],
    qdiiDeferralEvents: [],
    executionReports: [],
    monthlyReviews: [],
    backupHealth: { status: 'UNTESTED', lastExportAt: null, lastRestoreDryRunAt: null, message: '尚未进行备份恢复校验' },
    migration: { status: 'NONE' },
  };
}

export function migratePortfolio(input?: LocalPortfolio | null): LocalPortfolio {
  const base = createEmptyPortfolio();
  if (!input || !input.values) return base;
  const legacyPremium = input.qdiiPremium ?? null;
  const hasV3Ledger = [3, 4, 5, 6].includes(input.schemaVersion);
  const migratedAt = new Date().toISOString();
  const values = { ...base.values, ...input.values };
  const legacyPositions = Object.fromEntries(ASSET_CODES.map((code) => {
    const value = Math.max(0, Number(values[code]) || 0);
    return [code, {
      code,
      inputMode: 'MARKET_VALUE',
      quantity: null,
      confirmedMarketValue: value,
      confirmedAt: value > 0 ? input.updatedAt : null,
      estimationStatus: value > 0 ? 'IMPLIED_QUANTITY' : 'UNCONFIRMED',
    } satisfies LocalPosition];
  })) as Partial<Record<AssetCode, LocalPosition>>;
  const legacyPolicy = input.householdPolicy;
  const hasDeprecatedPolicy = Boolean(input.ipsPolicy || input.fundBuckets || input.householdPolicy);
  const migratedPolicy: IPSPolicy = input.ipsPolicy ? { ...emptyIPSPolicy(), ...input.ipsPolicy } : {
    ...emptyIPSPolicy(),
    enabled: legacyPolicy?.enabled ?? false,
    status: legacyPolicy?.enabled ? 'DRAFT' : 'UNSET',
    emergencyFundReady: legacyPolicy?.emergencyFundReady ?? null,
    householdEquityCap: legacyPolicy?.householdEquityCap ?? null,
    liabilityEquityCap: legacyPolicy?.liabilityEquityCap ?? null,
    horizonYears: legacyPolicy?.horizonYears ?? null,
    maxTolerableDrawdown: legacyPolicy?.maxTolerableDrawdown ?? null,
  };
  migratedPolicy.status = resolveIPSPolicyStatus(migratedPolicy);
  const fundBuckets: FundBuckets = {
    ...emptyFundBuckets(),
    ...(input.fundBuckets ?? {}),
    emergencyReserveExcluded: input.fundBuckets?.emergencyReserveExcluded
      ?? (legacyPolicy?.emergencyFundReady === true ? true : null),
  };
  return {
    ...base,
    ...input,
    schemaVersion: 6,
    values,
    positionsByCode: { ...legacyPositions, ...(input.positionsByCode ?? {}) },
    qdiiPremiums: {
      ...base.qdiiPremiums,
      ...(input.qdiiPremiums ?? {}),
      '513100': legacyPremium != null ? legacyPremium : input.qdiiPremiums?.['513100'] ?? null,
    },
    qdiiPremiumUpdatedAtByCode: {
      ...base.qdiiPremiumUpdatedAtByCode,
      ...(input.qdiiPremiumUpdatedAtByCode ?? {}),
      '513100': input.qdiiPremiumUpdatedAt ?? input.qdiiPremiumUpdatedAtByCode?.['513100'] ?? null,
    },
    monthlyContribution: input.plannedMonthlyContribution ?? input.monthlyContribution ?? 0,
    plannedMonthlyContribution: input.plannedMonthlyContribution ?? input.monthlyContribution ?? 0,
    baseline: input.baseline ?? null,
    snapshots: Array.isArray(input.snapshots) ? input.snapshots : [],
    cashFlows: Array.isArray(input.cashFlows) ? input.cashFlows : [],
    corrections: Array.isArray(input.corrections) ? input.corrections : [],
    ...(hasDeprecatedPolicy ? { ipsPolicy: migratedPolicy, fundBuckets } : {}),
    adviceRecords: Array.isArray(input.adviceRecords) ? input.adviceRecords : [],
    adviceStatusEvents: Array.isArray(input.adviceStatusEvents) ? input.adviceStatusEvents : [],
    qdiiDeferrals: Array.isArray(input.qdiiDeferrals) ? input.qdiiDeferrals : [],
    qdiiDeferralEvents: Array.isArray(input.qdiiDeferralEvents) ? input.qdiiDeferralEvents : [],
    executionReports: Array.isArray(input.executionReports) ? input.executionReports : [],
    monthlyReviews: Array.isArray(input.monthlyReviews) ? input.monthlyReviews : [],
    backupHealth: input.backupHealth ?? base.backupHealth,
    migration: hasV3Ledger ? input.migration ?? { status: 'NONE' } : {
      status: 'MIGRATED_PENDING_CONFIRMATION',
      sourceDatabase: 'fraiss-v3-private',
      migratedAt,
      message: '旧市值已保留；确认当前持仓后才建立资产基线，不回填历史收益。',
    },
    ...(hasDeprecatedPolicy ? { householdPolicy: {
      enabled: migratedPolicy.enabled,
      emergencyFundReady: migratedPolicy.emergencyFundReady,
      householdEquityCap: migratedPolicy.householdEquityCap,
      liabilityEquityCap: migratedPolicy.liabilityEquityCap,
      horizonYears: migratedPolicy.horizonYears,
      maxTolerableDrawdown: migratedPolicy.maxTolerableDrawdown,
    } } : {}),
  };
}

export function currentPositionValues(
  positions: Partial<Record<AssetCode, LocalPosition>>,
  assets: PublicAsset[],
): { values: Partial<Record<AssetCode, number>>; accuracy: 'CONFIRMED' | 'ESTIMATED'; issues: string[] } {
  const values: Partial<Record<AssetCode, number>> = {};
  const issues: string[] = [];
  let accuracy: 'CONFIRMED' | 'ESTIMATED' = 'CONFIRMED';
  ASSET_CODES.forEach((code) => {
    const position = positions[code];
    const asset = assets.find((item) => item.code === code);
    if (!position) { values[code] = 0; return; }
    if (position.inputMode === 'QUANTITY') {
      const quantity = Number(position.quantity);
      const price = asset?.valuationClose;
      if (!Number.isFinite(quantity) || quantity < 0) issues.push(`${code}份额无效`);
      if (price == null || !Number.isFinite(price) || price <= 0) issues.push(`${code}缺少未复权估值价`);
      values[code] = issues.some((issue) => issue.startsWith(code)) ? 0 : quantity * Number(price);
    } else {
      const value = Number(position.confirmedMarketValue);
      if (!Number.isFinite(value) || value < 0) issues.push(`${code}市值无效`);
      values[code] = Number.isFinite(value) && value >= 0 ? value : 0;
      if ((values[code] ?? 0) > 0) accuracy = 'ESTIMATED';
    }
    if (position.estimationStatus !== 'CONFIRMED' && (values[code] ?? 0) > 0) accuracy = 'ESTIMATED';
  });
  return { values, accuracy, issues };
}

export function confirmPortfolio(
  raw: LocalPortfolio,
  inputs: PositionInput[],
  assets: PublicAsset[],
  cash: number,
  now: string,
  cashFlow?: CashFlowInput | null,
): LocalPortfolio {
  const portfolio = migratePortfolio(raw);
  const positionsByCode = { ...(portfolio.positionsByCode ?? {}) };
  inputs.forEach(({ code, inputMode, amount }) => {
    positionsByCode[code] = {
      code,
      inputMode,
      quantity: inputMode === 'QUANTITY' ? amount : null,
      confirmedMarketValue: inputMode === 'MARKET_VALUE' ? amount : null,
      confirmedAt: now,
      estimationStatus: 'CONFIRMED',
    };
  });
  const valuation = currentPositionValues(positionsByCode, assets);
  if (valuation.issues.length) throw new Error(valuation.issues.join('；'));
  if (!Number.isFinite(cash) || cash < 0) throw new Error('现金不能为负数');
  const totalAssets = Object.values(valuation.values).reduce((sum, value) => sum + (value ?? 0), 0) + cash;
  const snapshotId = recordId('snapshot', now);
  const date = now.slice(0, 10);
  const snapshots = [...(portfolio.snapshots ?? [])];
  const previousSameDate = [...snapshots].reverse().find((item) => item.asOf === date && !item.supersededBy);
  const corrections = [...(portfolio.corrections ?? [])];
  if (previousSameDate) {
    previousSameDate.supersededBy = snapshotId;
    corrections.push({
      id: recordId('correction', now), createdAt: now, type: 'SNAPSHOT_SUPERSEDED',
      previousId: previousSameDate.id, replacementId: snapshotId,
    });
  }
  snapshots.push({
    id: snapshotId,
    asOf: date,
    positionsByCode: structuredClone(positionsByCode),
    values: { ...valuation.values },
    cash,
    totalAssets,
    source: 'USER_CONFIRMED',
    accuracy: valuation.accuracy,
    priceDate: assets.map((asset) => asset.valuationPriceDate).filter(Boolean).sort().at(0) ?? date,
    createdAt: now,
  });
  const cashFlows = [...(portfolio.cashFlows ?? [])];
  if (cashFlow && cashFlow.amount > 0) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(cashFlow.date)) throw new Error('现金流日期无效');
    cashFlows.push({ ...cashFlow, valuationEffectiveDate: null, id: recordId('cashflow', now), createdAt: now });
  }
  return {
    ...portfolio,
    schemaVersion: 6,
    updatedAt: now,
    positionsByCode,
    values: valuation.values,
    cash,
    baseline: portfolio.baseline ?? (totalAssets > 0 ? { date, totalAssets, performanceNav: 1, createdAt: now } : null),
    snapshots,
    cashFlows,
    corrections,
    migration: { status: 'COMPLETE', migratedAt: portfolio.migration?.migratedAt, sourceDatabase: portfolio.migration?.sourceDatabase },
  };
}

export function activeSnapshots(portfolio: LocalPortfolio) {
  return (portfolio.snapshots ?? []).filter((item) => !item.supersededBy).sort((a, b) => a.asOf.localeCompare(b.asOf));
}

export function activeCashFlows(portfolio: LocalPortfolio) {
  return (portfolio.cashFlows ?? []).filter((item) => !item.supersededBy).sort((a, b) => a.date.localeCompare(b.date));
}

export function voidCashFlow(raw: LocalPortfolio, cashFlowId: string, now: string): LocalPortfolio {
  const portfolio = migratePortfolio(raw);
  const cashFlows = [...(portfolio.cashFlows ?? [])];
  const index = cashFlows.findIndex((item) => item.id === cashFlowId && !item.supersededBy);
  if (index < 0) throw new Error('现金流记录不存在或已经作废');
  const voidId = recordId('void', now);
  cashFlows[index] = { ...cashFlows[index]!, supersededBy: voidId };
  return {
    ...portfolio,
    cashFlows,
    corrections: [...(portfolio.corrections ?? []), {
      id: recordId('correction', now), createdAt: now, type: 'CASH_FLOW_VOIDED',
      previousId: cashFlowId, replacementId: voidId,
    }],
  };
}

export function appendAdviceRecord(
  raw: LocalPortfolio,
  record: LocalAdviceRecord,
  deferrals: QDIIDeferral[] = [],
): LocalPortfolio {
  const portfolio = migratePortfolio(raw);
  if ((portfolio.adviceRecords ?? []).some((item) => item.adviceId === record.adviceId)) {
    throw new Error('本期建议已经留痕，不会重复覆盖');
  }
  return {
    ...portfolio,
    adviceRecords: [...(portfolio.adviceRecords ?? []), structuredClone(record)],
    adviceStatusEvents: [...(portfolio.adviceStatusEvents ?? []), {
      id: recordId('advice-status', record.createdAt), adviceId: record.adviceId,
      status: 'UNEXECUTED', createdAt: record.createdAt, note: '建议已保存，等待家庭人工复核',
    }],
    qdiiDeferrals: [...(portfolio.qdiiDeferrals ?? []), ...structuredClone(deferrals)],
  };
}

export function appendAdviceStatus(
  raw: LocalPortfolio,
  adviceId: string,
  status: AdviceStatusEvent['status'],
  now: string,
  note = '',
): LocalPortfolio {
  const portfolio = migratePortfolio(raw);
  if (!(portfolio.adviceRecords ?? []).some((item) => item.adviceId === adviceId)) throw new Error('建议记录不存在');
  if (status === 'PARTIAL' || status === 'EXECUTED') throw new Error('部分执行或已执行必须先填写真实成交并完成现金对账');
  return {
    ...portfolio,
    adviceStatusEvents: [...(portfolio.adviceStatusEvents ?? []), {
      id: recordId('advice-status', now), adviceId, status, createdAt: now, note: note.trim(),
    }],
  };
}

export function recordExecutionReport(
  raw: LocalPortfolio,
  input: ExecutionReportInput,
  assets: PublicAsset[],
  now: string,
): LocalPortfolio {
  const portfolio = migratePortfolio(raw);
  const advice = (portfolio.adviceRecords ?? []).find((item) => item.adviceId === input.adviceId);
  if (!advice) throw new Error('建议记录不存在');
  const currentStatus = latestAdviceStatus(portfolio, input.adviceId)?.status ?? advice.status;
  if (['EXECUTED', 'SKIPPED', 'EXPIRED'].includes(currentStatus)) throw new Error('该建议已结束，不能追加成交回报');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(input.tradeDate)) throw new Error('成交日期无效');
  const fills = input.fills.filter((fill) => fill.shares > 0);
  if (!fills.length) throw new Error('至少填写一笔真实成交');
  fills.forEach((fill) => {
    if (!ASSET_CODES.includes(fill.code)) throw new Error(`未知标的 ${fill.code}`);
    if (!Number.isInteger(fill.shares) || fill.shares <= 0) throw new Error(`${fill.code}成交份额必须为正整数`);
    if (!Number.isFinite(fill.price) || fill.price <= 0) throw new Error(`${fill.code}成交价无效`);
    if (!Number.isFinite(fill.fee) || fill.fee < 0) throw new Error(`${fill.code}费用无效`);
  });
  const duplicateCodes = fills.map((fill) => fill.code).filter((code, index, all) => all.indexOf(code) !== index);
  if (duplicateCodes.length) throw new Error('同一标的请合并为一笔成交回报');
  const cashBefore = portfolio.cash;
  const cashDelta = fills.reduce((sum, fill) => {
    const signedNotional = fill.shares * fill.price * (fill.side === 'BUY' ? -1 : 1);
    return sum + signedNotional - fill.fee;
  }, 0);
  const expectedCashAfter = cashBefore + cashDelta;
  if (!Number.isFinite(input.actualCashAfter) || input.actualCashAfter < 0) throw new Error('成交后现金无效');
  const cashDifference = input.actualCashAfter - expectedCashAfter;
  const tolerance = Math.max(1, (Object.values(portfolio.values).reduce((sum, value) => sum + (value ?? 0), 0) + cashBefore) * .0001);
  if (Math.abs(cashDifference) > tolerance) {
    throw new Error(`现金对账差额 ${cashDifference.toFixed(2)} 元超过容差 ${tolerance.toFixed(2)} 元，请核对成交价、费用和现金余额`);
  }
  const nextPositions = structuredClone(portfolio.positionsByCode ?? {});
  fills.forEach((fill) => {
    const position = nextPositions[fill.code] ?? emptyPositions()[fill.code]!;
    const signedShares = fill.side === 'BUY' ? fill.shares : -fill.shares;
    if (position.inputMode === 'QUANTITY') {
      const nextQuantity = (position.quantity ?? 0) + signedShares;
      if (nextQuantity < 0) throw new Error(`${fill.code}卖出份额超过本机记录`);
      nextPositions[fill.code] = { ...position, quantity: nextQuantity, confirmedAt: now, estimationStatus: 'CONFIRMED' };
    } else {
      const nextValue = (position.confirmedMarketValue ?? portfolio.values[fill.code] ?? 0) + signedShares * fill.price;
      if (nextValue < -1) throw new Error(`${fill.code}卖出金额超过本机记录`);
      nextPositions[fill.code] = { ...position, confirmedMarketValue: Math.max(0, nextValue), confirmedAt: now, estimationStatus: 'CONFIRMED' };
    }
  });
  const positionInputs = ASSET_CODES.map((code): PositionInput => {
    const position = nextPositions[code] ?? emptyPositions()[code]!;
    return {
      code,
      inputMode: position.inputMode,
      amount: position.inputMode === 'QUANTITY' ? position.quantity ?? 0 : position.confirmedMarketValue ?? 0,
    };
  });
  let reconciled = confirmPortfolio(portfolio, positionInputs, assets, input.actualCashAfter, now);
  const snapshotId = activeSnapshots(reconciled).at(-1)?.id;
  if (!snapshotId) throw new Error('成交后持仓快照未建立');
  const reportId = recordId('execution', now);
  reconciled = {
    ...reconciled,
    executionReports: [...(reconciled.executionReports ?? []), {
      id: reportId, adviceId: input.adviceId, status: input.status, tradeDate: input.tradeDate,
      createdAt: now, fills: structuredClone(fills), cashBefore, expectedCashAfter,
      actualCashAfter: input.actualCashAfter, cashDifference,
      reconciliationStatus: 'PASS', postTradeSnapshotId: snapshotId, note: input.note.trim(),
    }],
    adviceStatusEvents: [...(reconciled.adviceStatusEvents ?? []), {
      id: recordId('advice-status', now), adviceId: input.adviceId, status: input.status,
      createdAt: now, note: `成交回报 ${reportId} 已通过现金与持仓对账`,
    }],
  };
  return reconciled;
}

export function latestDeferralStatus(portfolio: LocalPortfolio, deferral: QDIIDeferral): QDIIDeferral['status'] {
  return (portfolio.qdiiDeferralEvents ?? []).filter((event) => event.deferralId === deferral.id)
    .sort((left, right) => left.createdAt.localeCompare(right.createdAt)).at(-1)?.status ?? deferral.status;
}

export function appendDeferralStatus(
  raw: LocalPortfolio,
  deferralId: string,
  status: QDIIDeferralEvent['status'],
  now: string,
  note = '',
): LocalPortfolio {
  const portfolio = migratePortfolio(raw);
  const deferral = (portfolio.qdiiDeferrals ?? []).find((item) => item.id === deferralId);
  if (!deferral) throw new Error('QDII延期记录不存在');
  const current = latestDeferralStatus(portfolio, deferral);
  const allowed: Record<QDIIDeferral['status'], QDIIDeferral['status'][]> = {
    DEFERRED: ['REVIEWED', 'EXPIRED'], REVIEWED: ['RELEASED', 'EXPIRED'], RELEASED: [], EXPIRED: [],
  };
  if (!allowed[current].includes(status)) throw new Error(`QDII延期不能从 ${current} 变更为 ${status}`);
  return {
    ...portfolio,
    qdiiDeferralEvents: [...(portfolio.qdiiDeferralEvents ?? []), {
      id: recordId('qdii-status', now), deferralId, status, createdAt: now, note: note.trim(),
    }],
  };
}

export function applyLifecycleExpirations(raw: LocalPortfolio, now: string): LocalPortfolio {
  let portfolio = migratePortfolio(raw);
  const today = now.slice(0, 10);
  for (const advice of portfolio.adviceRecords ?? []) {
    const status = latestAdviceStatus(portfolio, advice.adviceId)?.status ?? advice.status;
    if (advice.expiresAt < today && ['UNEXECUTED', 'PARTIAL'].includes(status)) {
      portfolio = appendAdviceStatus(portfolio, advice.adviceId, 'EXPIRED', now, '建议超过有效期，自动转为只读历史');
    }
  }
  for (const deferral of portfolio.qdiiDeferrals ?? []) {
    const status = latestDeferralStatus(portfolio, deferral);
    if (deferral.reviewDate < today && ['DEFERRED', 'REVIEWED'].includes(status)) {
      portfolio = appendDeferralStatus(portfolio, deferral.id, 'EXPIRED', now, '延期未在复核期内释放，不自动追补');
    }
  }
  return portfolio;
}

export function appendMonthlyReview(raw: LocalPortfolio, review: MonthlyReview): LocalPortfolio {
  const portfolio = migratePortfolio(raw);
  if ((portfolio.monthlyReviews ?? []).some((item) => item.month === review.month)) throw new Error('本月检查单已经保存');
  return { ...portfolio, monthlyReviews: [...(portfolio.monthlyReviews ?? []), structuredClone(review)] };
}

export function latestAdviceStatus(portfolio: LocalPortfolio, adviceId: string): AdviceStatusEvent | undefined {
  return (portfolio.adviceStatusEvents ?? []).filter((event) => event.adviceId === adviceId)
    .sort((left, right) => left.createdAt.localeCompare(right.createdAt)).at(-1);
}

export function validateLocalPortfolio(portfolio: LocalPortfolio, assets: PublicAsset[]): string[] {
  const issues: string[] = [];
  if (!Number.isFinite(portfolio.cash) || portfolio.cash < 0) issues.push('现金为负数或无效');
  ASSET_CODES.forEach((code) => {
    const value = portfolio.values[code] ?? 0;
    if (!Number.isFinite(value) || value < 0) issues.push(`${code}市值为负数或无效`);
    const position = portfolio.positionsByCode?.[code];
    if (!position) return;
    const amount = position.inputMode === 'QUANTITY' ? position.quantity : position.confirmedMarketValue;
    if (amount != null && (!Number.isFinite(amount) || amount < 0)) issues.push(`${code}${position.inputMode === 'QUANTITY' ? '份额' : '市值'}无效`);
    if (position.inputMode === 'QUANTITY' && (amount ?? 0) > 0 && !assets.find((asset) => asset.code === code)?.valuationClose) issues.push(`${code}缺少未复权估值价`);
  });
  const active = activeSnapshots(portfolio);
  const activeDates = active.map((item) => item.asOf);
  if (new Set(activeDates).size !== activeDates.length) issues.push('存在重复的有效资产快照');
  const snapshotIds = (portfolio.snapshots ?? []).map((item) => item.id);
  if (new Set(snapshotIds).size !== snapshotIds.length) issues.push('存在重复的资产快照编号');
  const flowIds = (portfolio.cashFlows ?? []).map((item) => item.id);
  if (new Set(flowIds).size !== flowIds.length) issues.push('存在重复的现金流编号');
  (portfolio.cashFlows ?? []).forEach((flow) => {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(flow.date)) issues.push(`${flow.id}现金流日期无效`);
    if (flow.valuationEffectiveDate != null && !/^\d{4}-\d{2}-\d{2}$/.test(flow.valuationEffectiveDate)) issues.push(`${flow.id}估值生效日无效`);
    if (!Number.isFinite(flow.amount) || flow.amount <= 0) issues.push(`${flow.id}现金流金额无效`);
  });
  // V5.0—V5.2 的家庭政策与资金桶只作为旧备份数据保留；V5.3 起不再校验、
  // 不再影响建议。组合范围由用户实际录入的持仓和现金明确界定。
  const adviceIds = (portfolio.adviceRecords ?? []).map((item) => item.adviceId);
  if (new Set(adviceIds).size !== adviceIds.length) issues.push('存在重复的建议记录编号');
  const adviceIdSet = new Set(adviceIds);
  const statusIds = (portfolio.adviceStatusEvents ?? []).map((item) => item.id);
  if (new Set(statusIds).size !== statusIds.length) issues.push('存在重复的建议状态事件编号');
  (portfolio.adviceStatusEvents ?? []).forEach((event) => {
    if (!adviceIdSet.has(event.adviceId)) issues.push(`${event.id}引用了不存在的建议`);
  });
  const deferralIds = (portfolio.qdiiDeferrals ?? []).map((item) => item.id);
  if (new Set(deferralIds).size !== deferralIds.length) issues.push('存在重复的QDII延期记录编号');
  if (portfolio.migration?.status === 'ERROR') issues.push(portfolio.migration.message ?? '旧数据迁移错误');
  return issues;
}
